					<AvatarImage src={person.image} />
					<AvatarFallback>{getInitials(person.name)}</AvatarFallback>
				</Avatar>
			))}
			<Avatar className="border-bg border-2 hover:z-10">
				<AvatarFallback>+7</AvatarFallback>
			</Avatar>
